from typing import Callable, Any

class Step:
    def __init__(self, name: str, fn: Callable[[Any], Any]):
        self.name = name
        self.fn = fn


def run_pipeline(payload: Any, steps: list[Step]) -> Any:
    state = payload
    for step in steps:
        state = step.fn(state)
    return state

export type Output = { text: string; confidence?: number }

export function enforceContract(output: Output): Output {
  const text = output.text?.trim() ?? ""
  return {
    text: text.length ? text : "No usable response generated.",
    confidence: output.confidence ?? 0
  }
}
